# TEMI · questões ilustradas (4.24.0) · bloco 1 — sepse e choque, hemodinâmica
# Formato: (tema, enunciado, [(alternativa, porquê) — a CORRETA primeiro], comentário, pegadinha, referência, figura)
import math
from fx import *

xs = [i * 0.5 for i in range(41)]
def gv(pk, tp): return [round(pk * (t / tp) ** 2 * math.exp(2 * (1 - t / tp)), 3) for t in xs]
pre = list(range(0, 21))
def fs(m): return [round(m * (1 - math.exp(-x / 5)), 1) for x in pre]

